import { useSyncExternalStore } from 'react';
import { useQuery } from '@tanstack/react-query';
import { useNavigate } from '@tanstack/react-router';
import { getJson } from '../../api/http';
import { useCurrentSheet } from '../session/session';
import type { Hold } from '../claims/claims';
import { asFlag, asString, useSearchParam } from '../../url/useSearchParam';

export const GRADES = ['A', 'B', 'C'] as const;

// `grade` is the grade in force on the sheet's today; `grades` every grade they were given with the date it
// applies from (null for the first, which applies from the beginning of time), by from-date.
// `version` is raised on every save; an edit sends the version it loaded and is refused (409) when
// someone else has saved the person since.
// `statementCount` is how many statements were taken for them; `statedTotal` and `statementDate` are the last
// one's due-total and the sheet's today when it was taken (null with none).
// `retiredFrom` is the date they are retired from (null: not retired); with one set they count as retired at
// once, whatever the date; from the day it is reached (the sheet's today on or after it) their OPEN and PENDING
// claims count in no live total, unless a statement binds them.
// `held`: whether they have any hold. `holds`: their holds, earliest from-date first; a hold takes none of their
// claims out of any total — while one covers the sheet's today they get no pool cut, their share spread over the others.
// `terms`: their own terms in days in force on the sheet's today (null: none); a claim of theirs is due by its date plus these, ahead of their
// grade's terms and the sheet's.
// `contact`: their contact, trimmed and lower-cased (null: none); no two people on a sheet share one.
// `aliases`: other names they go by, sorted ignoring case; the quick-add bar and the paste box find them by one too.
// `clashing`: whether their name or an alias is in use on another sheet of the sheet's tree (its ancestors and
// descendants); an edit of them through the person form is refused until it leaves them no longer clashing.
// `origin`: the sheet they were transferred from (null: they were not transferred here).
// `retirements`: their past retirements, each ended by an unretire, earliest from-date first: from a date to the
// day they were unretired; a claim dated after the from and before the to is refused, as one after a retirement is.
// `tags`: their tags, trimmed, lower-cased and sorted, without repeats (empty: none); the tag totals count each
// claim of theirs for these as well as for the claim's own.
// `snapshots`: one per SNAPSHOT written for them as the sheet's today moved on, oldest first: the day being left
// and their due-total on it (n/a with none).
// `statements`: their statements still standing (a cancelled one is gone), by the date each was taken as of,
// oldest first (those a merge or transfer brought over among them): that date and the due-total it recorded.
// `flag`: the reason a steward flagged them with, while the sheet's today is on or before the flag's until-date
// (null: no flag in force); only a steward may open their claims then.
// `approver`: the user who may approve or reject their PENDING claims as a steward may (null: none).
// `patronIds`: the other people on the sheet they have named as patrons, in the order they were named.
import { HomeMain } from '../../slots/defs/homeMain';
import { useCurrentSheet, useCurrentUser, useSheetToday } from '../session/session';
import { GRADES } from '../people/people';
import { rateOn, useRates } from './rates';

// The rate calendar: for each grade and each month of the sheet's today's calendar year, the rate in force on the
// first day of that month (as the rate in force today is found: up the sheet's parents when it has none), n/a when none.
function RateCalendar() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const today = useSheetToday();
  const rates = useRates();
  if (!user || !sheet || today === undefined) return null;
  const year = today.slice(0, 4);
  const months = Array.from({ length: 12 }, (_, i) => `${year}-${String(i + 1).padStart(2, '0')}`);
  return (
    <section data-testid="rate-calendar">
      <h2>Rate calendar {year}</h2>
      <table>
        <thead>
          <tr>
            <th>Grade</th>
            {months.map((m) => (
              <th key={m}>{m}</th>
            ))}
          </tr>
        </thead>
        <tbody>
          {GRADES.map((g) => (
            <tr key={g}>
              <td>{g}</td>
              {months.map((m) => (
                <td key={m} data-testid={`rate-month-${g}-${m}`}>
                  {rateOn(rates.data, g, `${m}-01`) ?? 'n/a'}
                </td>
              ))}
            </tr>
          ))}
        </tbody>
      </table>
    </section>
  );
}

export const contribution = HomeMain.fill({ order: 5.2, Component: RateCalendar });
import { HomeMain } from '../../slots/defs/homeMain';
import { useCurrentSheet, useCurrentUser, useSheetToday } from '../session/session';
import { GRADES, gradeOn, usePeople } from '../people/people';
import { isReviewLate, useClaims } from '../claims/claims';
import { personDue } from '../rates/due.slot';
import { diffDue, sumDue, useRates } from '../rates/rates';
import { useSettings } from '../roles/roles';
import { periodDue, usePeriods } from '../periods/periods';
import { isActive } from '../claims/active.slot';
import { useVoidReasons } from '../voidreasons/voidreasons';
import { usePools } from '../pools/pools';

/** The statuses the summary counts claims by. */
export const STATUSES = ['DRAFT', 'OPEN', 'PENDING', 'SETTLED', 'VOID', 'REVIEW'] as const;

// The summary panel, figured the same way as the list: per grade, how many people not retired have it in force on
// the sheet's today, their due-totals added up (skipping n/a) and how many of them are active; per period (by from-date), its due-total and its change from
// the period before it (none for the earliest); per status, how
// many of the sheet's claims have it, and how many REVIEW claims are late in review; per reason on the sheet's list of void reasons, how many VOID claims were voided with it.
function Summary() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const people = usePeople();
  const claims = useClaims();
  const rates = useRates();
  const periods = usePeriods();
  const settings = useSettings();
  const pools = usePools();
  const today = useSheetToday();
  const voidReasons = useVoidReasons();
  if (!user || !sheet) return null;
  const current = (people.data ?? []).filter((p) => p.retiredFrom === null);
  const allClaims = claims.data ?? [];
  const sortedPeriods = [...(periods.data ?? [])].sort((a, b) => (a.from < b.from ? -1 : a.from > b.from ? 1 : 0));
  const periodDues = sortedPeriods.map((p) => periodDue(p, people.data, allClaims, rates.data, settings.data, today));
  return (
    <section data-testid="summary">
      <h2>Summary</h2>
      <table>
        <thead>
          <tr>
            <th>Grade</th>
            <th>People</th>
            <th>Due</th>
            <th>Active</th>
          </tr>
        </thead>
        <tbody>
          {GRADES.map((g) => {
            const onGrade = current.filter((p) => gradeOn(p, today) === g);
            return (
              <tr key={g}>
                <td>{g}</td>
                <td data-testid={`summary-grade-${g}-count`}>{onGrade.length}</td>
                <td data-testid={`summary-grade-${g}-due-total`}>
                  {sumDue(onGrade.map((p) => personDue(p, allClaims, rates.data, today, settings.data, people.data, pools.data)))}
                </td>
                <td data-testid={`summary-grade-${g}-active`}>
                  {onGrade.filter((p) => isActive(p, allClaims, today)).length}
                </td>
              </tr>
            );
          })}
        </tbody>
      </table>
      <table>
        <thead>
          <tr>
            <th>Period</th>
            <th>Due</th>
            <th>Change</th>
          </tr>
        </thead>
        <tbody>
          {sortedPeriods.map((p, i) => (
            <tr key={p.id}>
              <td>{p.name}</td>
              <td data-testid={`summary-period-${p.name}-due-total`}>{periodDues[i]}</td>
              <td data-testid={`summary-period-${p.name}-change`}>
                {i === 0 ? '' : diffDue(periodDues[i], periodDues[i - 1])}
              </td>
            </tr>
          ))}
        </tbody>
      </table>
      <table>
        <thead>
          <tr>
            <th>Status</th>
            <th>Claims</th>
          </tr>
        </thead>
        <tbody>
          {STATUSES.map((s) => (
            <tr key={s}>
              <td>{s}</td>
              <td data-testid={`summary-status-${s}-count`}>{allClaims.filter((c) => c.status === s).length}</td>
            </tr>
          ))}
          <tr>
            <td>REVIEW late</td>
            <td data-testid="summary-review-late-count">
              {allClaims.filter((c) => isReviewLate(c, today, settings.data)).length}
            </td>
          </tr>
        </tbody>
      </table>
      <table>
        <thead>
          <tr>
            <th>Void reason</th>
            <th>Claims</th>
          </tr>
        </thead>
        <tbody>
          {(voidReasons.data ?? []).map((r) => (
            <tr key={r.id}>
              <td>{r.reason}</td>
              <td data-testid={`summary-void-${r.reason}-count`}>
                {allClaims.filter((c) => c.status === 'VOID' && c.voidReason === r.reason).length}
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </section>
  );
}

export const contribution = HomeMain.fill({ order: 33, Component: Summary });

